import{_ as a,o as s,c as o,a0 as n}from"./chunks/framework.DqMqoJl9.js";const m=JSON.parse('{"title":"Frame 和 window","description":"","frontmatter":{},"headers":[],"relativePath":"browser/7-frame-window.md","filePath":"browser/7-frame-window.md","lastUpdated":1791573371000}'),l={name:"browser/7-frame-window.md"};function p(i,e,c,r,t,d){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="frame-和-window" tabindex="-1">Frame 和 window <a class="header-anchor" href="#frame-和-window" aria-label="Permalink to &quot;Frame 和 window&quot;">​</a></h1><h2 id="_1-弹窗和-window-的方法" tabindex="-1">1 弹窗和 window 的方法 <a class="header-anchor" href="#_1-弹窗和-window-的方法" aria-label="Permalink to &quot;1 弹窗和 window 的方法&quot;">​</a></h2><p>目前弹窗并不常用，但仍然有一些任务在使用弹窗，例如进行 <code>OAuth</code> 授权，因为：弹窗是一个独立的窗口，具有自己的独立 JavaScript 环境。因此，使用弹窗打开一个不信任的第三方网站是安全的</p><h3 id="_1-1-阻止弹窗" tabindex="-1">1.1 阻止弹窗 <a class="header-anchor" href="#_1-1-阻止弹窗" aria-label="Permalink to &quot;1.1 阻止弹窗&quot;">​</a></h3><p>很多恶意网站经常滥用弹窗。因此，现在大多数浏览器都会通过阻止弹窗来保护用户</p><p>如果弹窗是在<strong>用户触发</strong>的事件处理程序（如 onclick）之外调用的，大多数浏览器都会阻止此类弹窗</p><h3 id="_1-2-window-open" tabindex="-1">1.2 window.open <a class="header-anchor" href="#_1-2-window-open" aria-label="Permalink to &quot;1.2 window.open&quot;">​</a></h3><p><strong>打开一个弹窗：</strong></p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> win </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> window.</span><span style="color:#6F42C1;">open</span><span style="color:#24292E;">(url, name, params);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>url</code> 要在新窗口中加载的 URL</li><li><code>name</code> 新窗口的名称。每个窗口都有一个 <code>window.name</code>，我们可以指定哪个窗口用于弹窗。如果已经有一个这样名字的窗口 —— 将在该窗口打开给定的 URL，否则会打开一个新窗口</li><li><code>params</code> 新窗口的配置字符串。它包括设置，用逗号分隔。参数之间不能有空格，例如：<code>width=200,height=100</code></li></ul><p><strong>params 参数：</strong></p><ul><li><code>left/top</code>（数字）—— 屏幕上窗口的左上角的坐标。这有一个限制：不能将新窗口置于屏幕外</li><li><code>width/height</code>（数字）—— 新窗口的宽度和高度。宽度/高度的最小值是有限制的，因此不可能创建一个不可见的窗口</li><li><code>menubar</code>（yes/no）—— 显示或隐藏新窗口的浏览器菜单</li><li><code>toolbar</code>（yes/no）—— 显示或隐藏新窗口的浏览器导航栏（后退，前进，重新加载等）</li><li><code>location</code>（yes/no）—— 显示或隐藏新窗口的 URL 字段。Firefox 和 IE 浏览器不允许默认隐藏它</li><li><code>status</code>（yes/no）—— 显示或隐藏状态栏。同样，大多数浏览器都强制显示它</li><li><code>resizable</code>（yes/no）—— 允许禁用新窗口大小调整。不建议使用</li><li><code>scrollbars</code>（yes/no）—— 允许禁用新窗口的滚动条。不建议使用</li></ul><p><strong>关闭弹窗：</strong></p><ul><li>关闭一个窗口：<code>win.close()</code></li><li>检查一个窗口是否被关闭：<code>win.closed</code></li></ul><p>从技术上讲，<code>close()</code> 方法可用于任何 <code>window</code>，但是如果 <code>window</code> 不是通过 <code>window.open()</code> 创建的，那么大多数浏览器都会忽略 <code>window.close()</code></p><p>如果窗口被关闭了，那么 <code>closed</code> 属性则为 <code>true</code>。这对于检查弹窗（或主窗口）是否仍处于打开状态很有用</p><p><strong>滚动和调整大小：</strong></p><ul><li><code>win.moveBy(x,y)</code> 将窗口相对于当前位置向右移动 x 像素，并向下移动 y 像素。允许负值（向上/向左移动）</li><li><code>win.moveTo(x,y)</code> 将窗口移动到屏幕上的坐标 (x,y) 处</li><li><code>win.resizeBy(width,height)</code> 根据给定的相对于当前大小的 <code>width/height</code> 调整窗口大小。允许负值</li><li><code>win.resizeTo(width,height)</code> 将窗口调整为给定的大小</li></ul><p><strong>仅对于弹窗</strong>。为了防止滥用，浏览器通常会阻止这些方法</p><blockquote><p><strong>没有最小化/最大化</strong>。JavaScript 无法最小化或者最大化一个窗口。这些操作系统级别的功能对于前端开发者而言是隐藏的</p></blockquote><h3 id="_1-3-同源策略" tabindex="-1">1.3 同源策略 <a class="header-anchor" href="#_1-3-同源策略" aria-label="Permalink to &quot;1.3 同源策略&quot;">​</a></h3><p>只有在窗口是同源的时，窗口才能自由访问彼此的内容</p><p><strong>从弹窗访问窗口：</strong></p><p>弹窗也可以使用 window.opener 来访问 opener 窗口。除了弹窗之外，对其他所有窗口来说，window.opener 均为 null</p><h3 id="_1-4-聚焦失焦" tabindex="-1">1.4 聚焦失焦 <a class="header-anchor" href="#_1-4-聚焦失焦" aria-label="Permalink to &quot;1.4 聚焦失焦&quot;">​</a></h3><p>从理论上讲，使用 <code>window.focus()</code> 和 <code>window.blur()</code>方法可以使窗口获得或失去焦点。此外，还有 <code>focus/blur</code> 事件，可以捕获到访问者聚焦到一个窗口和切换到其他地方的时刻</p><blockquote><p>在实际中它们被进行了严格地限制，因为恶意网站会滥用这些方法。浏览器必须引入很多限制，以禁用此类代码并保护用户免受广告和恶意页面的侵害</p></blockquote><h2 id="_2-跨窗口通信" tabindex="-1">2 跨窗口通信 <a class="header-anchor" href="#_2-跨窗口通信" aria-label="Permalink to &quot;2 跨窗口通信&quot;">​</a></h2><h3 id="_2-1-同源" tabindex="-1">2.1 同源 <a class="header-anchor" href="#_2-1-同源" aria-label="Permalink to &quot;2.1 同源&quot;">​</a></h3><p><strong>同源策略规定：</strong></p><ul><li>如果我们有对另外一个窗口的引用，并且该窗口是同源的，那么我们就具有对该窗口的全部访问权限</li><li>如果窗口不是同源的，那么我们就无法访问该窗口中的内容：变量，文档，任何东西</li><li><strong>唯一的例外</strong>是 <code>location</code>：我们可以修改它（进而重定向用户）。但是我们无法读取 <code>location</code></li></ul><h3 id="_2-2-document-domain" tabindex="-1">2.2 document.domain <a class="header-anchor" href="#_2-2-document-domain" aria-label="Permalink to &quot;2.2 document.domain&quot;">​</a></h3><p>根据定义，两个具有不同域的 URL 具有不同的源。</p><p>但是，如果窗口的二级域相同，例如 <code>john.site.com</code>，<code>peter.site.com</code> 和 <code>site.com</code>（它们共同的二级域是 <code>site.com</code>），我们可以使浏览器忽略该差异，使得它们可以被作为“同源”的来对待，以便进行跨窗口通信</p><p>为了做到这一点，每个这样的窗口都应该执行下面这行代码：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">document.domain </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;site.com&#39;</span><span style="color:#24292E;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-3-window-frames" tabindex="-1">2.3 window.frames <a class="header-anchor" href="#_2-3-window-frames" aria-label="Permalink to &quot;2.3 window.frames&quot;">​</a></h3><p>可以从 <code>window.frames</code> 获取 <code>iframe</code> 的 window 对象：</p><ul><li>通过索引获取：<code>window.frames[0]</code> —— 文档中的第一个 iframe 的 window 对象</li><li>通过名称获取：<code>window.frames.iframeName</code> —— 获取 <code>name=&quot;iframeName&quot;</code> 的 iframe 的 window 对象</li></ul><p>一个 iframe 内可能嵌套了其他的 iframe。相应的 window 对象会形成一个层次结构：</p><ul><li><code>window.frames</code> —— 子窗口的集合（用于嵌套的 iframe）</li><li><code>window.parent</code> —— 对父（外部）窗口的引用</li><li><code>window.top</code> —— 对最顶级父窗口的引用</li></ul><h3 id="_2-4-sandbox" tabindex="-1">2.4 sandbox <a class="header-anchor" href="#_2-4-sandbox" aria-label="Permalink to &quot;2.4 sandbox&quot;">​</a></h3><p><code>sandbox</code> 属性允许在 <code>&lt;iframe&gt;</code> 中禁止某些特定行为，以防止其执行不被信任的代码。它通过将 <code>iframe</code> 视为非同源的，或者应用其他限制来实现 <code>iframe</code> 的沙盒化</p><p><code>&lt;iframe sandbox src=&quot;...&quot;&gt;</code> 默认的属性为最严格的限制</p><p>可以通过参数配置相关限制：</p><ul><li><code>allow-same-origin</code> 默认情况下，sandbox 会为 iframe 强制实施 “不同来源” 的策略。它使浏览器将 iframe 视为来自另一个源，即使其 src 指向的是同一个网站也是如此。具有所有隐含的脚本限制。此选项会移除这些限制</li><li><code>allow-top-navigation</code> 允许 iframe 更改 parent.location</li><li><code>allow-forms</code> 允许在 iframe 中提交表单</li><li><code>allow-scripts</code> 允许在 iframe 中运行脚本</li><li><code>allow-popups</code> 允许在 iframe 中使用 window.open 打开弹</li></ul><h3 id="_2-5-跨窗口通信" tabindex="-1">2.5 跨窗口通信 <a class="header-anchor" href="#_2-5-跨窗口通信" aria-label="Permalink to &quot;2.5 跨窗口通信&quot;">​</a></h3><p><code>postMessage</code> 接口允许窗口之间相互通信，无论是否同源</p><p>想要发送消息的窗口需要调用接收窗口的 postMessage 方法</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">win.</span><span style="color:#6F42C1;">postMessage</span><span style="color:#24292E;">(data, targetOrigin) </span><span style="color:#6A737D;">// win 为接收窗口</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>参数：</strong></p><ul><li><code>data</code> 要发送的数据。可以是任何对象，数据会被通过使用结构化序列化算法进行克隆。IE 浏览器只支持字符串，因此我们需要对复杂的对象调用 <code>JSON.stringify</code> 方法进行处理，以支持该浏览器</li><li><code>targetOrigin</code> 指定目标窗口的源，以便只有来自给定的源的窗口才能获得该消息</li></ul><blockquote><p><code>targetOrigin</code> 是一种安全措施。如果目标窗口是非同源的，我们无法在发送方窗口读取它的 <code>location</code>。因此，我们无法确定当前在预期的窗口中打开的是哪个网站：用户随时可以导航离开，并且发送方窗口对此一无所知</p></blockquote><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">iframe</span><span style="color:#6F42C1;"> src</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;http://example.com&quot;</span><span style="color:#6F42C1;"> name</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;example&quot;</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#D73A49;">  let</span><span style="color:#24292E;"> win </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> window.frames.example;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">  win.</span><span style="color:#6F42C1;">postMessage</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;message&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;http://example.com&quot;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>onmessage</strong></p><p>目标接口接收消息事件</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">window.</span><span style="color:#6F42C1;">addEventListener</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;message&quot;</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">function</span><span style="color:#24292E;">(</span><span style="color:#E36209;">event</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#D73A49;">  if</span><span style="color:#24292E;"> (event.origin </span><span style="color:#D73A49;">!=</span><span style="color:#032F62;"> &#39;http://javascript.info&#39;</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#D73A49;">    return</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">  console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">( </span><span style="color:#032F62;">&quot;received: &quot;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> event.data );</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">  // 可以使用 event.source.postMessage(...) 向回发送消息</span></span>
<span class="line"><span style="color:#24292E;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>event 对象具有特殊属性：</strong></p><ul><li><code>data</code> 从 postMessage 传递来的数据</li><li><code>origin</code> 发送方的源</li><li><code>source</code> 对发送方窗口的引用</li></ul><h2 id="_3-点击劫持攻击" tabindex="-1">3 点击劫持攻击 <a class="header-anchor" href="#_3-点击劫持攻击" aria-label="Permalink to &quot;3 点击劫持攻击&quot;">​</a></h2><p>诱导点击透明的 iframe，iframe 内嵌被攻击的网站</p><h3 id="_3-1-传统防御" tabindex="-1">3.1 传统防御 <a class="header-anchor" href="#_3-1-传统防御" aria-label="Permalink to &quot;3.1 传统防御&quot;">​</a></h3><p>禁止页面在 iframe 打开</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">if</span><span style="color:#24292E;"> (top </span><span style="color:#D73A49;">!=</span><span style="color:#24292E;"> window) {</span></span>
<span class="line"><span style="color:#24292E;">  top.location </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> window.location;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这个方法并不可靠，有许多方式可以绕过这个限制：</p><p><strong>阻止顶级导航：</strong></p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">window.</span><span style="color:#6F42C1;">onbeforeunload</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> function</span><span style="color:#24292E;">() {</span></span>
<span class="line"><span style="color:#D73A49;">  return</span><span style="color:#005CC5;"> false</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>当 <code>iframe</code> 试图更改 <code>top.location</code> 时，访问者会收到一条消息，询问他们是否要离开页面。在大多数情况下，访问者会做出否定的回答</p><p><strong>Sandbox 特性：</strong></p><p><code>sandbox</code> 特性的限制之一就是导航。沙箱化的 <code>iframe</code> 不能更改 <code>top.location</code></p><p>添加具有 <code>sandbox=&quot;allow-scripts allow-forms&quot;</code> 的 <code>iframe</code>，允许脚本和表单。没添加 <code>allow-top-navigation</code>，因此更改 <code>top.location</code> 是被禁止的</p><h3 id="_3-2-x-frame-options" tabindex="-1">3.2 X-Frame-Options <a class="header-anchor" href="#_3-2-x-frame-options" aria-label="Permalink to &quot;3.2 X-Frame-Options&quot;">​</a></h3><p>服务器端 <code>header</code> <code>X-Frame-Options</code> 可以允许或禁止在 frame 中显示页面。</p><p>参数：</p><ul><li><code>DENY</code> 始终禁止在 frame 中显示此页面</li><li><code>SAMEORIGIN</code> 允许在和父文档同源的 frame 中显示此页面</li><li><code>ALLOW-FROM domain</code> 允许在来自给定域的父文档的 frame 中显示此页面</li></ul><h3 id="_3-3-显示禁用的功能" tabindex="-1">3.3 显示禁用的功能 <a class="header-anchor" href="#_3-3-显示禁用的功能" aria-label="Permalink to &quot;3.3 显示禁用的功能&quot;">​</a></h3><p><code>X-Frame-Options</code> 有一个副作用。其他的网站即使有充分的理由也无法在 frame 中显示我们的页面</p><p>可以用一个 <code>div</code> 覆盖整个页面，判断 <code>window === top</code> 或者确认不需要防护时，将 <code>div</code> 删除</p><h3 id="_3-4-samesite-cookie-特性" tabindex="-1">3.4 Samesite cookie 特性 <a class="header-anchor" href="#_3-4-samesite-cookie-特性" aria-label="Permalink to &quot;3.4 Samesite cookie 特性&quot;">​</a></h3><p>具有 <code>samesite</code> 特性的 <code>cookie</code> 仅在网站是通过直接方式打开（而不是通过 frame 或其他方式）的情况下才发送到网站</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>Set-Cookie: authorization=secret; samesite</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>当不使用 <code>cookie</code> 时，<code>samesite cookie</code> 特性将不会有任何影响。这可以使其他网站能够轻松地在 <code>iframe</code> 中显示我们公开的、未进行身份验证的页面。</p><p>然而，这也可能会使得劫持攻击在少数情况下起作用。例如，通过检查 <code>IP</code> 地址来防止重复投票的匿名投票网站仍然会受到点击劫持的攻击，因为它不使用 <code>cookie</code> 对用户身份进行验证</p>`,83)])])}const b=a(l,[["render",p]]);export{m as __pageData,b as default};
